2773f808-9fea-46fa-96f7-7713ef577ec8	3d778a42-8957-4fcc-909e-b22d7d8fde64	<CAMpMsptsUggYNhYm-OHv-1fN8=tf1dqTwwNJ7L+3XR_q2o4c4w@mail.gmail.com>	EMAIL	ORDER	{"id": "AAMkAGUwNWEyYWNiLWJiZmMtNGVhYS1hNjI4LWMwNTcxN2U2NDhkNQBGAAAAAACnmkWfBcR7QJIFP_7xkQVRBwDjsLOgeeDySrc96zrOmMKkAAAAAAEMAADjsLOgeeDySrc96zrOmMKkAAGIyPFqAAA=", "body": {"content": "Hi,\\r\\n\\r\\nI'm Inaam from Jack & Ross, working on behalf of Criterion Development Ltd.\\r\\n\\r\\nI'm reaching out regarding some materials we need.\\r\\nBe advised it is a relatively long list of items so thanks in advance\\r\\nfor having a look at it\\r\\nWe require the following:\\r\\n\\r\\n• M3 x 8mm Grub Dog (Allen) Screw PK100 — 1 pack\\r\\n• Cramer Profiling Tool Kit 10 Pieces — 4 each\\r\\n• LED 2.5W G9 Pro Capsule 2700K — 10 each\\r\\n• Termtech CFK180 Fuse Kit — 1 pack\\r\\n• 15mm x 3m Copper Tube (BS EN 1057) — 2 length\\r\\n• 22mm x 3m Copper Tube (BS EN 1057) — 2 length\\r\\n• 28mm x 3m Copper Tube (BS EN 1057) — 2 length\\r\\n• Sanha 22mm Copper Press Coupling — 20 each\\r\\n• Sanha 15mm Copper Press Coupling — 20 each\\r\\n• Sanha 28mm Copper Press Coupling — 10 each\\r\\n• Floplast ABS WS12 90° Bend 50mm White — 45 each\\r\\n• Floplast 50mm x 3m Solvent Pipe White — 6 length\\r\\n• Black Swan PVC Cement 236ml — 10 each\\r\\n• Solvent Cleaner 250ml — 10 each\\r\\n• Muuto Tip Wall Lamp Black — 10 each\\r\\n• Mapei 113 Cement Grey Silicone Sealant — 24 each\\r\\n• Everbuild Timber & Laminate Paintable Sealant Oak — 24 each\\r\\n• Gorilla Mounting Tape 1.5m Clear — 5 each\\r\\n• LEILUO 6 Pcs Diamond Multi Tool Accessory Kit — 4 each\\r\\n• Isiflex Shower Hose 1.60m Chrome — 5 each\\r\\n• Energizer AA Industrial Battery (10-pack) — 20 pack\\r\\n• Altech TMV 15mm 2-in-1 TMV2/3 — 5 each\\r\\n• Avalon/Sola Toilet Seat & Cover Grey — 2 each\\r\\n• Roman Showers Innov8 Bifold Shower Screen Hinge — 2 each\\r\\n\\r\\nCould you please provide:\\r\\n1. Unit price and total for each item\\r\\n2. Availability and lead time\\r\\n3. Delivery charges to Central London\\r\\n4. Any bulk discounts available\\r\\n\\r\\nWe need quotes as soon as possible.\\r\\n\\r\\nPlease don't hesitate to call me on 07534471536 if you need any clarification.\\r\\n\\r\\nKind regards,\\r\\n\\r\\nInaam\\r\\nBuyer – Jack & Ross | Criterion Developments\\r\\nTel: 07534 471536\\r\\nEmail: IECSprocurement@gmail.com\\r\\n", "contentType": "text"}, "from": {"emailAddress": {"name": "Inaam - Jack & Ross", "address": "iecsprocurement@gmail.com"}}, "_folder": "INBOX", "subject": "Quote Request", "@odata.etag": "W/\\"CQAAABYAAADjsLOgeeDySrc96zrOmMKkAAGH4rGR\\"", "bodyPreview": "Hi,\\r\\n\\r\\nI'm Inaam from Jack & Ross, working on behalf of Criterion Development Ltd.\\r\\n\\r\\nI'm reaching out regarding some materials we need.\\r\\nBe advised it is a relatively long list of items so thanks in advance\\r\\nfor having a look at it\\r\\nWe require the follow", "ccRecipients": [], "toRecipients": [{"emailAddress": {"name": "Majid Al Jassas", "address": "majid.aljassas@cromwellplumbing.co.uk"}}], "conversationId": "AAQkAGUwNWEyYWNiLWJiZmMtNGVhYS1hNjI4LWMwNTcxN2U2NDhkNQAQALuypR_198VDljqRaPEmRxw=", "hasAttachments": false, "receivedDateTime": "2026-04-15T13:47:50Z", "internetMessageId": "<CAMpMsptsUggYNhYm-OHv-1fN8=tf1dqTwwNJ7L+3XR_q2o4c4w@mail.gmail.com>"}	\N	2026-04-15 13:47:50	\N	ACTIONED	[ack-matcher] skipped QUOTE: quote keyword	2026-04-16 09:14:08.145
