"address": "John.Baker@stgeorges.nhs.uk"}}], "toRecipients": [{"emailAddress": {"name": "Alin Asofronie", "address": "Alin.Asofronie@stgeorges.nhs.uk"}}], "conversationId": "AAQkAGUwNWEyYWNiLWJiZmMtNGVhYS1hNjI4LWMwNTcxN2U2NDhkNQAQAIt4O3-b-T1CrWTanCSbakc=", "hasAttachments": false, "receivedDateTime": "2026-04-01T09:35:17Z", "internetMessageId": "<CWXP123MB175255111FAC055C0F8DFA93A450A@CWXP123MB1752.GBRP123.PROD.OUTLOOK.COM>"}	\N	2026-04-01 09:35:17	\N	ACTIONED	\N	2026-04-16 09:15:55.576
d9255dcc-1985-4ce0-abb1-9003c29e7e5b	3d778a42-8957-4fcc-909e-b22d7d8fde64	<2025987454.2106202.1775060443745@poczta.home.pl>	EMAIL	ORDER	{"id": "AAMkAGUwNWEyYWNiLWJiZmMtNGVhYS1hNjI4LWMwNTcxN2U2NDhkNQBGAAAAAACnmkWfBcR7QJIFP_7xkQVRBwDjsLOgeeDySrc96zrOmMKkAAAAAAEMAADjsLOgeeDySrc96zrOmMKkAAGAEhY4AAA=", "body": {"content": "<html><head>\\r\\n<meta http-equiv=\\"Content-Type\\" content=\\"text/html; charset=utf-8\\"></head><body><div>Hi Majid. </div><div class=\\"default-style\\">&nbsp; </div><div class=\\"default-style\\">I have attached a drawing of our standard showerlay. Its for 800mm x 800mm but generally the only difference with the larger trays is the size and drain length. Generally the rule is that the drain length is 300mm less than the side of the showerlay on which it lies. So a 1200mm showerlay width with a 900mm drain, that's 150mm each side of the drain to the edge (D1) and 150mm from the edge of the showerlay to the side of the drain (C1). </div><div class=\\"default-style\\">&nbsp; </div><div class=\\"default-style\\">With a 20mm thick showerlay, the linear drain body will pertrude from the underside of the showerlay. This would need some thought on a wooden floor but not on a screeded concrete floor </div><div class=\\"default-style\\"><div>With 30mm and 40mm the linear drain body is more or less level with the underside&nbsp; of the showerlay. </div><div class=\\"default-style\\">&nbsp; </div><div class=\\"default-style\\">All are produced from XPS foam covered both sides in a cementous coating and reinforced net. The drain is factory built into the foam and is waterproofed into place. </div><div class=\\"default-style\\">&nbsp; </div><div class=\\"default-style\\">All showerlays have slopes from each corner to the corner of the linear drain. </div><div class=\\"default-style\\">&nbsp; </div><div class=\\"default-style\\">As with all cement coated showerlays, they must be waterproofed before tiling. </div><div class=\\"default-style\\">&nbsp; </div><div class=\\"default-style\\">I hope this helps. </div><div class=\\"default-style\\">&nbsp; </div><div class=\\"default-style\\">Thanks. </div><div class=\\"default-style\\">&nbsp; </div><div class=\\"default-style\\">John. </div><div>&nbsp; </div><p><img src=\\"cid:part1.w73e53Lf.ozl370g0@wiper.pl\\" alt=\\"\\"></p></div><div class=\\"default-style\\">&nbsp; </div><div class=\\"io-ox-signature\\"><p class=\\"ox-c9d5a7a3da-ox-1413ca3091-MsoNormal\\">Best regards<br>John Hilton<br>Export Sales Director</p><p class=\\"ox-c9d5a7a3da-ox-1413ca3091-MsoNormal\\"><br><img id=\\"e7c39969-5769-4eec-9476-add8f1680b0f\\" src=\\"cid:e7c39969-5769-4eec-9476-add8f1680b0f\\" alt=\\"\\" style=\\"max-width:100%\\"><br>&nbsp;e-mail: <a class=\\"mailto-link\\" href=\\"mailto:johnhilton@wiper.pl\\"><u><span style=\\"color:#007dbc\\">johnhilton@wiper.pl</span></u></a><br>tel.: +48 32 738 50 00 | mob.: +48 515 286 062<br>WIPER Sp. z o.o., ul. Kolejowa 2, 43-190 Mikołów, Polska <br>NIP 635-16-05-660, KRS 0000212232 <br><a href=\\"http://www.wiper.pl/\\"><u><span style=\\"color:#007dbc\\">www.wiper.pl</span></u></a> <a class=\\"mailto-link\\" href=\\"mailto:poczta@wiper.pl\\"><u><span style=\\"color:#007dbc\\">poczta@wiper.pl</span></u></a></p><p>&nbsp;</p></div></body></html>", "contentType": "html"}, "from": {"emailAddress": {"name": "John Hilton", "address": "johnhilton@wiper.pl"}}, "_folder": "INBOX", "subject": "Tech Drawing", "@odata.etag": "W/\\"CQAAABYAAADjsLOgeeDySrc96zrOmMKkAAF/MZVt\\"", "bodyPreview": "Hi Majid.\\r\\n\\r\\nI have attached a drawing of our standard showerlay. Its for 800mm x 800mm but generally the only difference with the larger trays is the size and drain length. Generally the rule is that the drain length is 300mm less than the side of the sh", "ccRecipients": [], "toRecipients": [{"emailAddress": {"name": "Majid Al Jassas", "address": "majid.aljassas@cromwellplumbing.co.uk"}}], "conversationId": "AAQkAGUwNWEyYWNiLWJiZmMtNGVhYS1hNjI4LWMwNTcxN2U2NDhkNQAQAPy8iOZgaX